INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES ("2023/06/30 12:00:00", -470.0, 1, 1.47, "クローチェ", 0.0, 10001, 1, "2023/09/22 14:59:59", 1, "いらっしゃいませっ♪\nキャラバンコインを使って\n買い物ができますよっ！", 2, 126401, 2002);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES ("2023/06/30 12:00:00", -470.0, 2, 2.15, "クローチェ", 0.0, 10002, 2, "2023/09/22 14:59:59", 1, "素敵な品が揃ってるので\nたーっくさん買っていって\nくださいねっ♪", 1, 126401, 2002);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES ("2023/06/30 12:00:00", -470.0, 1, 0.0, "ライラエル", 0.0, 10003, 2, "2023/09/22 14:59:59", 1, "ショップへようこそ\nキャラバンコインはこちら\nで買い物に使えますよ", 2, 126501, 2002);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES ("2023/06/30 12:00:00", -470.0, 2, 0.0, "ライラエル", 0.0, 10004, 1, "2023/09/22 14:59:59", 1, "こちらのショップで\n買い物をして、素敵な\n旅を楽しんでくださいね", 1, 126501, 2002);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES ("2023/09/15 15:00:00", -470.0, 1, 0.0, "リンド", 0.0, 10005, 2, "2023/12/22 14:59:59", 2, "いらっしゃいませ\nキャラバンコインを使って\nお買い物ができますよ", 2, 127702, 2002);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES ("2023/09/15 15:00:00", -470.0, 2, 0.0, "リンド", 0.0, 10006, 2, "2023/12/22 14:59:59", 2, "ショップの掃除は完璧です\n姫さま直営のお店として\n当然のことですから", 2, 127702, 2002);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES ("2023/09/15 15:00:00", -470.0, 1, 0.0, "ヴルム", 0.0, 10007, 1, "2023/12/22 14:59:59", 2, "ショップへようこそ\nキャラバンコインと品物を\n交換できるんで、よければ", 1, 127802, 2002);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES ("2023/09/15 15:00:00", -470.0, 2, 6.5, "ヴルム", 0.0, 10008, 2, "2023/12/22 14:59:59", 2, "なんで店番なんか…\nま、やりますけど\n好きな品物をどうぞ", 1, 127802, 2002);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES ("2023/12/15 15:00:00", -470.0, 1, 0.0, "アネモネ", 0.0, 10009, 2, "2024/03/22 14:59:59", 3, "──いらっしゃいませ\n買い物しても、いいですよ\nキャラバンコインがあれば", 1, 129602, 2002);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES ("2023/12/15 15:00:00", -470.0, 2, 0.0, "アネモネ", 0.0, 10010, 2, "2024/03/22 14:59:59", 3, "──もっと笑顔がほしい？\nいくらコインを積まれても\n売れない物はありますから", 1, 129602, 2002);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES ("2023/12/15 15:00:00", -470.0, 1, 0.0, "ネフィ=ネラ", 0.0, 10011, 1, "2024/03/22 14:59:59", 3, "ようこそおいでなんし\nキャラバンコインをこちら\nで交換して進ぜんしょう", 1, 129701, 2002);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES ("2023/12/15 15:00:00", -470.0, 2, 6.2, "ネフィ=ネラ", 0.0, 10012, 2, "2024/03/22 14:59:59", 3, "ところで、お前さまは\nいくらで贖えるのか喃？\n──フフ、冗談でありんす", 1, 129701, 2002);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES ("2024/03/15 15:00:00", -470.0, 1, 3.1, "カノン", 0.0, 10013, 3, "2024/06/22 14:59:59", 4, "い、いらっしゃいませっ！\n…くっ…このあたくし様が\n店番なんて…屈辱ですわっ", 5, 130301, 2002);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES ("2024/03/15 15:00:00", -470.0, 2, 6.15, "カノン", 0.0, 10014, 3, "2024/06/22 14:59:59", 4, "あら、あたくしをご所望？\nお生憎様、そんな小銭では\n…買えちゃうんですの！？", 2, 130301, 2002);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES ("2024/03/15 15:00:00", -470.0, 1, 0.0, "ナーナ", 0.0, 10015, 2, "2024/06/22 14:59:59", 4, "いらっしゃいませ～♪\nきゃらばんこいん？を\n交換できるんだってー", 2, 130401, 2002);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES ("2024/03/15 15:00:00", -470.0, 2, 3.35, "ナーナ", 0.0, 10016, 2, "2024/06/22 14:59:59", 4, "甘いのくれたら、\nお礼にナーナの拾った\n松ぼっくりあげちゃうよ！", 1, 130401, 2002);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES ("2024/06/15 15:00:00", -470.0, 1, 0.0, "ホウオウ", 0.0, 10017, 1, "2024/09/22 14:59:59", 5, "ショップへようこそ\nこの鳳凰が、皆さんに\n祝福を差し上げましょう", 1, 130502, 2002);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES ("2024/06/15 15:00:00", -470.0, 2, 3.18, "ホウオウ", 0.0, 10018, 2, "2024/09/22 14:59:59", 5, "ほーちゃんと呼ぶ権利は\n売っていませんよ？\n騎士さんへの、特別です！", 1, 130502, 2002);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES ("2024/06/15 15:00:00", -470.0, 3, 0.0, "ホウオウ", 0.0, 10019, 4, "2024/09/22 14:59:59", 5, "うﾞぇぇえんっ！まﾞだごの\n格好になっぢゃいまじだ！\n寄付をお願いじまず～っ！", 4, 130503, 2002);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES ("2024/06/15 15:00:00", -470.0, 1, 4.9, "ネア", 0.0, 10020, 1, "2024/09/22 14:59:59", 5, "おっすー♪\nなんでも交換してけー\nカリザきゅん以外で", 2, 123301, 2002);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES ("2024/06/15 15:00:00", -470.0, 2, 4.8, "ネア", 0.0, 10021, 1, "2024/09/22 14:59:59", 5, "ところで、騎士きゅんは\nおいくら万ルピ？\nジョーダンぬ・き・で♡", 2, 123301, 2002);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES ("2024/09/15 15:00:00", -470.0, 1, 4.922, "カリザ", 0.0, 10022, 3, "2024/12/22 14:59:59", 6, "ケッ、なんでオレ様が店番\nなんざ…って来んなキイロ\nオレは売りモンじゃねー！", 1, 133301, 2002);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES ("2024/09/15 15:00:00", -470.0, 2, 9.638, "カリザ", 0.0, 10023, 3, "2024/12/22 14:59:59", 6, "い、言わなきゃダメか？\n「…いらっしゃいませ…」\nクソッ、笑うんじゃねー！", 5, 133301, 2002);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES ("2024/09/15 15:00:00", -470.0, 1, 2.88, "ミーア", 0.0, 10024, 1, "2024/12/22 14:59:59", 6, "ショップへようこそ～\nネラさまの腹心…的な私が\n店番させていただきま～す", 2, 133401, 2002);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES ("2024/09/15 15:00:00", -470.0, 2, 4.818, "ミーア", 0.0, 10025, 5, "2024/12/22 14:59:59", 6, "私の抜け殻とか、\n需要ありますかね～…\nって冗談ですよ、冗談！", 1, 133401, 2002);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES ("2024/12/15 15:00:00", -470.0, 1, 1.78, "グレイス", 0.0, 10026, 2, "2025/03/22 14:59:59", 7, "へい、らっしゃい\nさ、騎士氏。冥土の土産は\nなにがいいですか？", 1, 133002, 2002);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES ("2024/12/15 15:00:00", -470.0, 2, 6.15, "グレイス", 0.0, 10027, 1, "2025/03/22 14:59:59", 7, "商品をお買い上げ毎に\nグレイスちゃんポイントを\n差し上げます。嘘ですが", 7, 133002, 2002);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES ("2024/12/15 15:00:00", -470.0, 1, 4.28, "ヴァイオレット", 0.0, 10028, 6, "2025/03/22 14:59:59", 7, "ようこそいらっしゃいませ\n…接客とは、このような\n振舞で宜しいでしょうか？", 2, 133102, 2002);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES ("2024/12/15 15:00:00", -470.0, 2, 0.0, "ヴァイオレット", 0.0, 10029, 1, "2025/03/22 14:59:59", 7, "じめじめした商品は\nございませんので\n安心してお買い求め下さい", 1, 133102, 2002);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES ("2025/03/15 15:00:00", -470.0, 1, 5.53, "ルルィ", 0.0, 10030, 2, "2025/06/23 14:59:59", 8, "いらっしゃいましぇでしゅ\n何をお求めでしゅか？\nたこ焼きもありましゅよ！", 1, 136902, 2002);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES ("2025/03/15 15:00:00", -470.0, 2, 6.05, "ルルィ", 0.0, 10031, 9, "2025/06/23 14:59:59", 8, "そのコイン…ピカピカで、\n集めたくなっちゃいましゅ\nタコ釣られされちゃう～…", 7, 136902, 2002);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES ("2025/03/15 15:00:00", -470.0, 1, 0.0, "デュラン", 0.0, 10032, 2, "2025/06/23 14:59:59", 8, "姫のご友人ならば\n礼儀を尽くすのが爺の務め\nさ、望みの物を言いたまえ", 1, 137001, 2002);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES ("2025/03/15 15:00:00", -470.0, 2, 0.0, "デュラン", 0.0, 10033, 2, "2025/06/23 14:59:59", 8, "キャラバンコインではなく\n首で支払って貰えんかのぅ\n…冗談であるぞ？", 1, 137001, 2002);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES ("2025/06/16 15:00:00", -470.0, 1, 0.0, "サツキ", 0.0, 10034, 2, "2025/09/23 14:59:59", 9, "おう\n好きなもん持ってきな", 2, 135902, 2002);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES ("2025/06/16 15:00:00", -470.0, 2, 4.935, "サツキ", 0.0, 10035, 1, "2025/09/23 14:59:59", 9, "宵越しの銭を持つような\n野暮いマネぁしくさんな\nツキが落ちてもしらねぇぜ", 6, 135902, 2002);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES ("2025/06/16 15:00:00", -470.0, 1, 7.441, "ユキノ", 0.0, 10036, 2, "2025/09/23 14:59:59", 9, "ら、ら、らっしゃっせ…\nなんかほしいもん、ある？\nか、かき氷とか、ど…？", 5, 135802, 2002);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES ("2025/06/16 15:00:00", -470.0, 2, 0.0, "ユキノ", 0.0, 10037, 7, "2025/09/23 14:59:59", 9, "そ、そんな見ねぇで…\nあては、売りもんじゃ\nねぇよ…？", 7, 135802, 2002);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES ("2025/09/16 15:00:00", -470.0, 1, 2.295, "クルル", 0.0, 10038, 2, "2025/12/22 14:59:59", 10, "クルルをお求めですかっ？\nそれならお礼に、こちらの\n宝石もどうぞですよ～♪", 2, 130901, 2002);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES ("2025/09/16 15:00:00", -470.0, 2, 6.281, "クルル", 0.0, 10039, 1, "2025/12/22 14:59:59", 10, "はっ！　ヒーローさんから\nお代なんて頂けないです！\nどうぞどうぞ…え、ダメ？", 6, 130901, 2002);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES ("2025/09/16 15:00:00", -470.0, 1, 5.549, "ヴォルガーノ", 0.0, 10040, 2, "2025/12/22 14:59:59", 10, "よぅ！　今日の俺さまは\n門番じゃなく、店番だぜ\nメモピ～スフィア～てな！", 1, 137701, 2002);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES ("2025/09/16 15:00:00", -470.0, 2, 2.64, "ヴォルガーノ", 0.0, 10041, 3, "2025/12/22 14:59:59", 10, "…リマさんのブロマイド？\n買い取るに決まってらぁ！\nなんでも持ってけ泥棒っ！", 6, 137701, 2002);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES ("2025/12/15 15:00:00", -470.0, 1, 7.642, "ライラエル", 0.0, 10042, 7, "2026/03/23 11:59:59", 11, "こ、この格好は…ヴルムが\n集客効果があると言って…\n…本当でしょうか？", 4, 132801, 2002);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES ("2025/12/15 15:00:00", -470.0, 2, 0.0, "ライラエル", 0.0, 10043, 1, "2026/03/23 11:59:59", 11, "この我に店番させるとは…\n全て買わねば許さぬぞ\n我が国庫に貢献するが良い", 1, 132802, 2002);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES ("2025/12/15 15:00:00", -470.0, 1, 0.0, "クローチェ", 0.0, 10044, 1, "2026/03/23 11:59:59", 11, "アナライズっ！\n本日のオススメ商品は～…\nこちらですっ♪", 1, 134502, 2002);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES ("2025/12/15 15:00:00", -470.0, 2, 3.72, "クローチェ", 0.0, 10045, 2, "2026/03/23 11:59:59", 11, "ギガンティックローチェ、\nおひとついかがですかっ？\n格納庫用意して下さいねっ", 1, 134501, 2002);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES ("2026/03/16 12:00:00", -470.0, 1, 4.991, "ネフィ＝ネラ", 0.0, 10046, 2, "2026/06/22 11:59:59", 12, "番頭も、飯事の如き営み\nなれば。愛らしき稚児らで\n千客万来といきませぬか喃", 1, 138201, 2002);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES ("2026/03/16 12:00:00", -470.0, 2, 3.877, "ネフィ＝ネラ", 0.0, 10047, 1, "2026/06/22 11:59:59", 12, "国を営むに金子は必須也…\nどうか御恵みくだしゃんせ\n誠心を以て報恩致しまする", 4, 138201, 2002);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES ("2026/03/16 12:00:00", -470.0, 1, 1.71, "アラクネ", 0.0, 10048, 4, "2026/06/22 11:59:59", 12, "あぅっ…！　天井が低くて\n頭をぶつけてしまって…\nわたしが、大きいだけ…？", 6, 136001, 2002);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES ("2026/03/16 12:00:00", -470.0, 2, 5.32, "アラクネ", 0.0, 10049, 5, "2026/06/22 11:59:59", 12, "いらっしゃいませ騎士さま\nくつろいでいって下さいね\nもし叶うなら…永遠に…", 2, 136001, 2002);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES ("2026/06/15 12:00:00", -470.0, 1, 3.727, "アネモネ", 0.0, 10050, 9, "2026/09/22 11:59:59", 13, "水着で、店番とか──\n本当、意味がわかりません\n海の家でもないのに…", 4, 135401, 2002);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES ("2026/06/15 12:00:00", -470.0, 2, 7.213, "アネモネ", 0.0, 10051, 7, "2026/09/22 11:59:59", 13, "──リアみたいに、\nもっと愛想良い接客を…\nいえ──なんでもないです", 9, 135401, 2002);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES ("2026/06/15 12:00:00", -470.0, 1, 1.874, "クリア", 0.0, 10052, 1, "2026/09/22 11:59:59", 13, "いらっしゃいませー♪\n奉仕活動兼、将来のために\nたくさん働いちゃいます♪", 2, 135301, 2002);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES ("2026/06/15 12:00:00", -470.0, 2, 0.0, "クリア", 0.0, 10053, 2, "2026/09/22 11:59:59", 13, "アルバイトが終わったら\n海に遊びに行きましょう！\nモネちゃんも一緒に♪", 2, 135301, 2002);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES ("2026/09/15 12:00:00", -470.0, 1, 4.215, "ヴァイオレット", 0.0, 10054, 2, "2026/12/22 11:59:59", 14, "大いなる命、神なる勇魚…\n慈しみの矜持を胸に素敵な\n商品をお売りいたします", 1, 138001, 2002);
